  for(i=0;i<l.length&&i<6;i++){var y=parseInt(l[i].slice(0,4),10),mo=parseInt(l[i].slice(5,7),10)-1;
    h+='<option value="'+l[i]+'"'+(i===0?' selected':'')+'>'+cap(MOIS[mo])+(y!==now.getFullYear()?' '+y:'')+'</option>';}
